contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length > 0, "empty tos");
        require(v.length == _tos.length, "length mismatch");

        address beforeFrom = c.from();
        address beforeCaddress = c.caddress();
        uint256 beforeBalance = address(c).balance;

        bool reverted;
        bool returned;
        try c.transfer(_tos, v) returns (bool r) {
            reverted = false;
            returned = r;
        } catch {
            reverted = true;
            returned = false;
        }

        address afterFrom = c.from();
        address afterCaddress = c.caddress();
        uint256 afterBalance = address(c).balance;

        assert(reverted || (returned && afterFrom == beforeFrom && afterCaddress == beforeCaddress && afterBalance == beforeBalance));
    }

    receive() external payable {}
}
